-- Okada assessment: entirely fictional training records, not company data.
-- MySQL 8.0+ / InnoDB. Import without --force into a NEW database.
-- Expected rows: players=10000, terminals=200, transactions=1000000.
-- Primary keys only. Relationship columns intentionally have no indexes or
-- enforced foreign keys; MySQL would auto-create indexes for enforced FKs.
CREATE DATABASE okada_assessment CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE okada_assessment;
SET NAMES utf8mb4;
CREATE TABLE players (
 player_id INT UNSIGNED NOT NULL PRIMARY KEY,
 display_name VARCHAR(60) NOT NULL,
 home_city VARCHAR(40) NOT NULL,
 loyalty_tier VARCHAR(12) NOT NULL
) ENGINE=InnoDB;
CREATE TABLE terminals (
 terminal_id INT UNSIGNED NOT NULL PRIMARY KEY,
 terminal_code VARCHAR(16) NOT NULL,
 floor_zone VARCHAR(40) NOT NULL,
 game_category VARCHAR(20) NOT NULL
) ENGINE=InnoDB;
CREATE TABLE transactions (
 transaction_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
 player_id INT UNSIGNED NOT NULL,
 terminal_id INT UNSIGNED NOT NULL,
 created_at DATETIME NOT NULL COMMENT 'UTC',
 transaction_type VARCHAR(12) NOT NULL,
 status VARCHAR(12) NOT NULL,
 amount_php DECIMAL(12,2) NOT NULL,
 reference_code VARCHAR(24) NOT NULL
) ENGINE=InnoDB;
